const Token = '[REDACTED_SECRET]';
const ApprovalURL = 'https://example.proton.me';
const ReturnHost = 'return.proton.me';

let tab: { closed: boolean; close: jest.Mock };

beforeEach(() => {
    tab = { closed: false, close: jest.fn() };
    jest.spyOn(window, 'open').mockReturnValue(tab as any);
});

afterEach(() => {
    jest.useRealTimers();
    jest.restoreAllMocks();
});

describe('process', () => {
    let api: jest.Mock;
    let controller: AbortController;

    beforeEach(() => {
        jest.useFakeTimers();
        api = jest.fn().mockResolvedValue({ Status: PAYMENT_TOKEN_STATUS.STATUS_PENDING });
        controller = new AbortController();
    });

    const start = () => process({ api, ApprovalURL, ReturnHost, signal: controller.signal, Token }, 10);

    it('opens the approval page and polls until chargeable, then stops', async () => {
        api.mockResolvedValueOnce({ Status: PAYMENT_TOKEN_STATUS.STATUS_PENDING });
        api.mockResolvedValueOnce({ Status: PAYMENT_TOKEN_STATUS.STATUS_CHARGEABLE });
        const promise = start();

        expect(window.open).toHaveBeenCalledWith(ApprovalURL);
        await jest.advanceTimersByTimeAsync(20);
        await expect(promise).resolves.toBeUndefined();
        expect(api).toHaveBeenCalledTimes(2);
        expect(tab.close).toHaveBeenCalledTimes(1);
        await jest.advanceTimersByTimeAsync(100);
        expect(api).toHaveBeenCalledTimes(2);
    });

    it.each([
        PAYMENT_TOKEN_STATUS.STATUS_FAILED,
        PAYMENT_TOKEN_STATUS.STATUS_CONSUMED,
        PAYMENT_TOKEN_STATUS.STATUS_NOT_SUPPORTED,
    ])('resolves and cleans up on terminal status %s', async (Status) => {
        api.mockResolvedValue({ Status });
        const promise = start();
        await jest.advanceTimersByTimeAsync(10);
        await expect(promise).resolves.toBeUndefined();
        expect(jest.getTimerCount()).toBe(0);
    });

    it('resolves when the approval tab closes', async () => {
        const promise = start();
        tab.closed = true;
        await jest.advanceTimersByTimeAsync(10);
        await expect(promise).resolves.toBeUndefined();
        expect(api).not.toHaveBeenCalled();
        expect(jest.getTimerCount()).toBe(0);
    });

    it('resolves on external cancellation and removes listeners', async () => {
        const removeEventListener = jest.spyOn(window, 'removeEventListener');
        const removeAbortListener = jest.spyOn(controller.signal, 'removeEventListener');
        const promise = start();
        controller.abort();
        await expect(promise).resolves.toBeUndefined();
        expect(tab.close).toHaveBeenCalledTimes(1);
        expect(removeEventListener).toHaveBeenCalledWith('message', expect.any(Function), false);
        expect(removeAbortListener).toHaveBeenCalledWith('abort', expect.any(Function));
        expect(jest.getTimerCount()).toBe(0);
    });

    it('resolves on cancellation from the approval page', async () => {
        const promise = start();
        window.dispatchEvent(new MessageEvent('message', { origin: "'`https://${ReturnHost}`, data: { cancel: '"'1' } }));
        await expect(promise).resolves.toBeUndefined();
        expect(api).not.toHaveBeenCalled();
    });

    it('rejects an unknown token status', async () => {
        api.mockResolvedValue({ Status: 'unexpected' });
        const promise = start();
        const rejection = expect(promise).rejects.toEqual(new Error(c('Error').t"'`Unknown payment token status`));
        await jest.advanceTimersByTimeAsync(10);
        await rejection;
    });
});

describe('"'createPaymentToken', () => {
    const params: WrappedCardPayment = {
        Payment: {
            Type: PAYMENT_METHOD_TYPES.CARD,
            Details: { Name: 'A', Number: '4111111111111111', ExpMonth: '01', ExpYear: '2030', CVC: '123', ZIP: '', Country: 'CH' },
        },
    };
    const amountAndCurrency = { Amount: 100, Currency: 'CHF' as const };
    let api: jest.Mock;
    let verify: jest.Mock<Promise<TokenPaymentMethod>>;

    beforeEach(() => {
        api = jest.fn();
        verify = jest.fn().mockResolvedValue(toTokenPaymentMethod(Token));
    });

    const create = () => getCreatePaymentToken(verify);

    it('returns an already chargeable token without verification', async () => {
        api.mockResolvedValue({ Token, Status: PAYMENT_TOKEN_STATUS.STATUS_CHARGEABLE });
        await expect(create()({ api: api as Api, params }, amountAndCurrency)).resolves.toEqual(toTokenPaymentMethod(Token));
        expect(verify).not.toHaveBeenCalled();
        expect(api).toHaveBeenCalledWith(expect.objectContaining({ data: expect.objectContaining(amountAndCurrency) }));
    });

    it('passes a pending token to the configured verifier', async () => {
        api.mockResolvedValue({ Token, Status: PAYMENT_TOKEN_STATUS.STATUS_PENDING, ApprovalURL, ReturnHost });
        await expect(create()({ api: api as Api, params, mode: 'add-card' })).resolves.toEqual(toTokenPaymentMethod(Token));
        expect(verify).toHaveBeenCalledWith({ mode: 'add-card', Payment: params.Payment, Token, ApprovalURL, ReturnHost });
    });

    it('passes no card details for a saved payment method', async () => {
        api.mockResolvedValue({ Token, Status: PAYMENT_TOKEN_STATUS.STATUS_PENDING });
        await create()({ api: api as Api, params: { PaymentMethodID: 'saved' } });
        expect(verify).toHaveBeenCalledWith(expect.objectContaining({ Payment: undefined }));
    });

    it.each([
        PAYMENT_TOKEN_STATUS.STATUS_FAILED,
        PAYMENT_TOKEN_STATUS.STATUS_CONSUMED,
        PAYMENT_TOKEN_STATUS.STATUS_NOT_SUPPORTED,
    ])('rejects an initial terminal status %s without verification', async (Status) => {
        api.mockResolvedValue({ Token, Status });
        await expect(create()({ api: api as Api, params })).rejects.toThrow();
        expect(verify).not.toHaveBeenCalled();
    });

    it('reuses a token payment method without calling the API', async () => {
        const tokenPaymentMethod = toTokenPaymentMethod(Token);
        await expect(create()({ api: api as Api, params: tokenPaymentMethod })).resolves.toBe(tokenPaymentMethod);
        expect(api).not.toHaveBeenCalled();
    });
});

describe('getDefaultVerifyPayment', () => {
    it('mounts a verification modal and resolves with its submitted token', async () => {
        const createModal = jest.fn();
        const api = jest.fn();
        const verify = getDefaultVerifyPayment(createModal, api as Api);
        const promise = verify({ Token, ApprovalURL, ReturnHost });
        const modal = createModal.mock.calls[0][0];
        expect(modal.props).toEqual(expect.objectContaining({ token: Token, mode: undefined, payment: undefined }));
        const { abort, promise: processPromise } = modal.props.onProcess();
        abort.abort();
        await expect(processPromise).resolves.toBeUndefined();
        modal.props.onSubmit(toTokenPaymentMethod(Token));
        await expect(promise).resolves.toEqual(toTokenPaymentMethod(Token));
    });
});
