const { STATUS_PENDING, STATUS_CHARGEABLE, STATUS_FAILED, STATUS_CONSUMED, STATUS_NOT_SUPPORTED } =
    PAYMENT_TOKEN_STATUS;

const DELAY_LISTENING = 1000;

/**
 * Open the approval tab and poll until the token reaches a terminal state, the tab closes, or the process is canceled.
 */
export const process = (
    {
        Token,
        api,
        ApprovalURL,
        ReturnHost,
        signal,
    }: Pick<PaymentTokenResult, 'ApprovalURL' | 'ReturnHost' | 'Token'> & {
        api: Api;
        signal: AbortSignal;
    },
    delayListening = DELAY_LISTENING
) => {
    const tab = window.open(ApprovalURL);

    return new Promise<void>((resolve, reject) => {
        let timer: ReturnType<typeof setTimeout> | undefined;
        let settled = false;

        const cleanup = () => {
            if (timer !== undefined) {
                clearTimeout(timer);
            }
            window.removeEventListener('message', onMessage, false);
            signal.removeEventListener('abort', abort);
        };

        const finish = () => {
            if (settled) {
                return;
            }
            settled = true;
            cleanup();
            tab?.close();
            resolve();
        };

        const fail = (error: unknown) => {
            if (settled) {
                return;
            }
            settled = true;
            cleanup();
            tab?.close();
            reject(error);
        };

        const checkStatus = async () => {
            if (settled) {
                return;
            }
            if (signal.aborted || tab?.closed) {
                finish();
                return;
            }
            try {
                const { Status } = await api({ ...getTokenStatus(Token), signal });
                if (settled) {
                    return;
                }
                if (Status === STATUS_PENDING) {
                    timer = setTimeout(checkStatus, delayListening);
                } else if (
                    Status === STATUS_CHARGEABLE ||
                    Status === STATUS_FAILED ||
                    Status === STATUS_CONSUMED ||
                    Status === STATUS_NOT_SUPPORTED
                ) {
                    finish();
                } else {
                    fail(new Error(c('Error').t`Unknown payment token status`));
                }
            } catch (error) {
                fail(error);
            }
        };

        const onMessage = (event: MessageEvent) => {
            if (getHostname(event.origin) !== ReturnHost) {
                return;
            }
            if (event.data?.cancel === '1') {
                finish();
            } else {
                if (timer !== undefined) {
                    clearTimeout(timer);
                }
                void checkStatus();
            }
        };

        const abort = () => finish();

        signal.addEventListener('abort', abort);
        window.addEventListener('message', onMessage, false);
        if (signal.aborted || tab?.closed) {
            finish();

